import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../../lib/cn";
import "../../styles/kbd.css";

/** Keyboard key hint, such as ⌘K. Decorative text, so it is read as plain text. */
export function Kbd({ className, ...props }: ComponentPropsWithoutRef<"kbd">) {
  return <kbd className={cn("eui-kbd", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Kbd. A small key cap with a hairline ring and a tabular mono face. */

.eui-kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: var(--eui-radius-sm);
  background-color: var(--eui-color-surface);
  color: var(--eui-color-fg-muted);
  box-shadow: inset 0 -1px 0 var(--eui-color-border-strong), inset 0 0 0 var(--eui-border-width) var(--eui-color-border);
  font-family: var(--eui-font-mono);
  font-size: 12px;
  line-height: 1;
}
